// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Microeconomics studies the choices of individuals and firms. Every choice involves trade-offs.","blocks":[{"t":"key","text":"Scarcity forces choices. Opportunity cost is the value of the next best alternative given up. Economic systems (market, command, mixed) answer what, how and for whom to produce."},{"t":"p","text":"The production possibilities curve (PPC) shows efficient combinations of two goods. A straight-line PPC means constant opportunity costs; a bowed-out PPC means increasing opportunity costs."},{"t":"p","text":"Comparative advantage (lower opportunity cost) determines who should specialize in what. Trade at terms between the two producers' opportunity costs benefits both."},{"t":"ex","problem":"Sam can make 10 pies or 5 cakes; Ava can make 6 pies or 6 cakes. Who has the comparative advantage in cakes?","steps":["Sam's cost of 1 cake: 2 pies. Ava's: 1 pie"],"answer":"Ava (lower opportunity cost)"}]},{"say":"Economists think at the margin: what is the benefit and cost of one more unit?","blocks":[{"t":"key","text":"Rational decision makers keep doing something as long as marginal benefit ≥ marginal cost. The optimal amount is where MB = MC."},{"t":"p","text":"Consumer choice: total utility rises as you consume more, but marginal utility (extra satisfaction from one more unit) usually diminishes."},{"t":"p","text":"Utility-maximizing rule: spend so that the marginal utility per dollar is equal across goods: MU_A/P_A = MU_B/P_B."},{"t":"ex","problem":"The 3rd pizza slice gives 12 utils at $3; the 2nd soda gives 8 utils at $2. Which is the better buy?","steps":["Pizza: 12/3 = 4 utils per dollar","Soda: 8/2 = 4 utils per dollar"],"answer":"They're equal, so this combination maximizes utility"}]}],[{"say":"Supply and demand determine prices. Elasticity tells how strongly buyers and sellers respond to price changes.","blocks":[{"t":"key","text":"Price elasticity of demand = %ΔQd ÷ %ΔP. Elastic (> 1): buyers are very responsive. Inelastic (< 1): not very responsive. Unit elastic = 1."},{"t":"p","text":"Demand is more elastic when there are many substitutes, the good is a luxury, it takes a large share of income, or there's more time to adjust."},{"t":"p","text":"Total revenue test: if demand is elastic, raising price lowers total revenue; if inelastic, raising price raises total revenue."},{"t":"p","text":"Other elasticities: income elasticity (normal goods > 0, inferior goods < 0) and cross-price elasticity (substitutes > 0, complements < 0)."},{"t":"ex","problem":"Price rises 10% and quantity demanded falls 20%. Elastic or inelastic?","steps":["Elasticity = 20/10 = 2"],"answer":"Elastic"}]},{"say":"Markets create value for buyers and sellers. Government interventions change who gains and who loses.","blocks":[{"t":"key","text":"Consumer surplus = what buyers are willing to pay − what they pay (area below demand, above price). Producer surplus = price − minimum acceptable price (area above supply, below price). Total surplus is maximized at the competitive equilibrium."},{"t":"p","text":"Deadweight loss is the lost total surplus when the market produces less (or more) than the efficient quantity."},{"t":"list","items":["Price ceilings (rent control) below equilibrium cause shortages and deadweight loss.","Price floors (minimum wage) above equilibrium cause surpluses.","Taxes create deadweight loss; the burden falls more on the more inelastic side of the market.","Subsidies increase quantity but can also create deadweight loss."]}]}],[{"say":"Firms combine inputs to make outputs. Understanding costs explains how much they produce.","blocks":[{"t":"key","text":"Diminishing marginal returns: as more workers are added to fixed capital, each additional worker eventually adds less output."},{"t":"p","text":"Costs: fixed costs (FC) don't change with output; variable costs (VC) do. Total cost TC = FC + VC. Average total cost ATC = TC/Q; marginal cost MC = ΔTC/ΔQ."},{"t":"p","text":"MC intersects AVC and ATC at their minimum points."},{"t":"p","text":"Long run: all inputs are variable. Economies of scale (falling long-run ATC) favor large firms; diseconomies of scale occur when firms grow too big."},{"t":"p","text":"Accounting profit = revenue − explicit costs; economic profit also subtracts implicit (opportunity) costs."}]},{"say":"Perfect competition is the benchmark market: many firms, identical products and no power over price.","blocks":[{"t":"key","text":"All firms maximize profit where MR = MC. In perfect competition, firms are price takers, so P = MR = demand."},{"t":"list","items":["Short run: firms can earn profits or losses. They shut down if P < AVC.","Long run: free entry and exit drive economic profit to zero; firms produce at minimum ATC."]},{"t":"p","text":"Perfect competition is both allocatively efficient (P = MC) and productively efficient (P = minimum ATC) in the long run."},{"t":"ex","problem":"A competitive firm faces a price of $10. At its MR = MC output, ATC is $8 and Q = 100. Profit?","steps":["Profit = (P − ATC) × Q = (10 − 8) × 100"],"answer":"$200 economic profit (which attracts new firms)"}]}],[{"say":"A monopoly is the only seller with no close substitutes. That gives it power to set prices.","blocks":[{"t":"key","text":"A monopoly's MR is below its demand curve. It produces where MR = MC, then charges the price on the demand curve at that quantity. It produces less and charges more than a competitive market, creating deadweight loss."},{"t":"p","text":"Barriers to entry include control of resources, patents, government licenses and economies of scale (natural monopolies like utilities)."},{"t":"p","text":"Price discrimination charges different customers different prices based on willingness to pay. Perfect price discrimination captures all consumer surplus but produces the efficient quantity."},{"t":"p","text":"Regulation of natural monopolies may set price at MC (socially optimal) or ATC (fair return)."}]},{"say":"Most real markets fall between perfect competition and monopoly. Strategy matters a lot in some of them.","blocks":[{"t":"key","text":"Monopolistic competition: many firms selling differentiated products (restaurants, clothing). Firms have some price power and advertise. In the long run, entry drives economic profit to zero, but firms have excess capacity."},{"t":"p","text":"Oligopoly: a few large firms (airlines, phone carriers) that are interdependent. Their decisions depend on rivals' choices, analyzed with game theory."},{"t":"p","text":"Game theory uses payoff matrices. A dominant strategy is best regardless of what the other player does. A Nash equilibrium is when neither player can improve by changing strategy alone. The prisoner's dilemma shows why cartels and collusion often break down."}]}],[{"say":"Firms buy inputs like labor in factor markets. Wages are set by supply and demand for workers.","blocks":[{"t":"key","text":"The demand for labor is derived from the demand for the products workers make. Marginal revenue product (MRP) = marginal product × marginal revenue. A firm hires until MRP = MRC (marginal resource cost)."},{"t":"p","text":"In a competitive labor market, MRC equals the wage, so firms hire until MRP = wage."},{"t":"p","text":"Labor demand shifts with product demand, productivity and the prices of other inputs. Labor supply shifts with population, preferences and opportunities elsewhere."},{"t":"ex","problem":"A worker adds 10 units of output that sell for $5 each. The wage is $40. Should the firm hire?","steps":["MRP = 10 × $5 = $50"],"answer":"Yes, since MRP ($50) > wage ($40)"}]},{"say":"When one employer dominates a labor market, it can pay lower wages. That's a monopsony.","blocks":[{"t":"key","text":"A monopsony is a single buyer of labor. Its MRC is above the labor supply curve, so it hires fewer workers and pays a lower wage than a competitive market."},{"t":"p","text":"A minimum wage can raise both employment and wages in a monopsony market (up to a point), unlike in a competitive market."},{"t":"p","text":"Least-cost rule: a firm minimizes costs when the marginal product per dollar is equal across inputs: MP_L/P_L = MP_K/P_K."},{"t":"p","text":"Income inequality comes from differences in skills, education, discrimination, inheritance and market power. The Lorenz curve and Gini coefficient measure it."}]}],[{"say":"Markets fail when people don't pay all the costs or get all the benefits of their actions.","blocks":[{"t":"key","text":"A negative externality (pollution) imposes costs on third parties, so the market overproduces: marginal social cost > marginal private cost. A positive externality (vaccines, education) gives benefits to others, so the market underproduces."},{"t":"p","text":"The socially optimal quantity is where marginal social benefit = marginal social cost."},{"t":"p","text":"Solutions: a per-unit (Pigouvian) tax equal to the external cost corrects negative externalities; a subsidy equal to the external benefit corrects positive externalities. Tradable pollution permits and regulations are other tools."}]},{"say":"Some goods won't be provided by markets at all. Governments step in, but every policy has trade-offs.","blocks":[{"t":"key","text":"Public goods are nonexcludable (you can't keep people from using them) and nonrival (one person's use doesn't reduce another's). Examples: national defense, lighthouses. The free-rider problem means markets underprovide them."},{"t":"p","text":"Common resources are nonexcludable but rival (fish in the ocean), leading to the tragedy of the commons (overuse)."},{"t":"p","text":"Income redistribution uses progressive taxes (higher rates for higher incomes), transfer payments and programs like the Earned Income Tax Credit. Regressive taxes take a larger share from lower incomes (like sales taxes, in effect)."},{"t":"p","text":"Government intervention can fail too (government failure), so policy must weigh costs and benefits."}]}]];
export default text;
